import java.security.Principal;
import java.util.List;
import sailpoint.object.Filter;
import sailpoint.object.Identity;
import sailpoint.object.QueryOptions;

Principal p = httpRequest.getUserPrincipal();
if (p == null || p.getName() == null || p.getName().length() == 0) {
    return null;
}
String upn = p.getName().trim().toLowerCase();
QueryOptions qo = new QueryOptions();
qo.addFilter(Filter.ignoreCase(Filter.eq("email", upn)));
qo.addFilter(Filter.eq("inactive", Boolean.FALSE));
List matches = context.getObjects(Identity.class, qo);
if (matches == null || matches.size() != 1) {
    log.warn("fsgov sso: " + (matches == null ? 0 : matches.size()) + " active identities match " + upn);
    return null;
}
return matches.get(0);
